/**
 * El próximo id DE LA SESIÓN, y avanza su marca para que no se repita.
 *
 * Si la sesión no tiene fila en `task_highwater`, la adopta de sus propias
 * filas de `tasks`: `MAX(task_id) + 1`, o 1 si no tiene ninguna — ciego a los
 * ids que la sesión ya borró antes de esta primera adopción, aceptado por
 * contrato (#311). Filas de otras sesiones no influyen: dos sesiones sí
 * pueden compartir el mismo `task_id`, porque `(session_id, task_id)` es la
 * clave primaria de `tasks`.
 *
 * Tiene que llamarse dentro de una transacción `BEGIN IMMEDIATE`: leer (o
 * adoptar) y avanzar la marca son dos sentencias, y sin la transacción dos
 * `TaskCreate` concurrentes pueden leer el mismo valor y chocar contra la
 * clave primaria de `tasks` en vez de recibir ids distintos.
 */
function nextTaskId(db: Database, sessionId: string): string {
  const marca = db.query('SELECT next_task_id AS n FROM task_highwater WHERE session_id = ?').get(sessionId) as
    | { n: number }
    | undefined
  if (marca) {
    db.run('UPDATE task_highwater SET next_task_id = ? WHERE session_id = ?', [marca.n + 1, sessionId])
    return String(marca.n)
  }
  const fila = db.query('SELECT MAX(CAST(task_id AS INTEGER)) AS n FROM tasks WHERE session_id = ?').get(sessionId) as {
    n: number | null
  }
  const id = (fila.n ?? 0) + 1
  db.run('INSERT INTO task_highwater (session_id, next_task_id) VALUES (?, ?)', [sessionId, id + 1])
  return String(id)
}
EOF

